CREATE TABLE public.master_plan_capability_library(code text PRIMARY KEY CHECK(code ~ '^[TFE][0-9]{2}$'),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object' AND payload->>'code'=code),criteria jsonb NOT NULL CHECK(jsonb_typeof(criteria)='array'),source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.master_plan_capability_library TO authenticated; GRANT ALL ON public.master_plan_capability_library TO service_role; ALTER TABLE public.master_plan_capability_library ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_capability_library_read ON public.master_plan_capability_library FOR SELECT TO authenticated USING(true);
CREATE TABLE public.master_plan_responsibility_library(source_id text PRIMARY KEY,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object' AND payload->>'sourceId'=source_id),source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.master_plan_responsibility_library TO authenticated; GRANT ALL ON public.master_plan_responsibility_library TO service_role; ALTER TABLE public.master_plan_responsibility_library ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_responsibility_library_read ON public.master_plan_responsibility_library FOR SELECT TO authenticated USING(true);
CREATE TABLE public.master_plan_library_metadata(library_key text PRIMARY KEY CHECK(library_key='responsabilidades-2026'),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.master_plan_library_metadata TO authenticated; GRANT ALL ON public.master_plan_library_metadata TO service_role; ALTER TABLE public.master_plan_library_metadata ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_library_metadata_read ON public.master_plan_library_metadata FOR SELECT TO authenticated USING(true);
CREATE TABLE public.master_plan_self_assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),collaborator_id uuid NOT NULL REFERENCES public.collaborators(id),capability_code text NOT NULL REFERENCES public.master_plan_capability_library(code),answers smallint[] NOT NULL CHECK(array_length(answers,1)=4 AND answers[1] BETWEEN 0 AND 3 AND answers[2] BETWEEN 0 AND 3 AND answers[3] BETWEEN 0 AND 3 AND answers[4] BETWEEN 0 AND 3),indicated_level smallint GENERATED ALWAYS AS(least(answers[1],answers[2],answers[3],answers[4])) STORED,comment text NOT NULL CHECK(length(trim(comment)) BETWEEN 1 AND 20000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.master_plan_self_assessments TO authenticated; GRANT ALL ON public.master_plan_self_assessments TO service_role; ALTER TABLE public.master_plan_self_assessments ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_self_assessments_read ON public.master_plan_self_assessments FOR SELECT TO authenticated USING(public.is_admin() OR collaborator_id=public.current_collaborator_id()); CREATE INDEX master_plan_self_assessments_person_date ON public.master_plan_self_assessments(collaborator_id,created_at DESC);
CREATE TABLE public.master_plan_certification_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),collaborator_id uuid NOT NULL REFERENCES public.collaborators(id),capability_code text NOT NULL REFERENCES public.master_plan_capability_library(code),target_level smallint NOT NULL CHECK(target_level BETWEEN 1 AND 3),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','changes_requested','approved')),responses jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(responses)='object' AND octet_length(responses::text)<=500000),reviews jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(reviews)='object' AND octet_length(reviews::text)<=200000),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz,decided_at timestamptz,reviewed_by uuid REFERENCES public.collaborators(id));
GRANT SELECT ON public.master_plan_certification_requests TO authenticated; GRANT ALL ON public.master_plan_certification_requests TO service_role; ALTER TABLE public.master_plan_certification_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_certification_requests_read ON public.master_plan_certification_requests FOR SELECT TO authenticated USING(public.is_admin() OR collaborator_id=public.current_collaborator_id()); CREATE INDEX master_plan_certification_requests_person_status ON public.master_plan_certification_requests(collaborator_id,status,created_at DESC); CREATE INDEX master_plan_certification_requests_queue ON public.master_plan_certification_requests(status,submitted_at DESC); CREATE UNIQUE INDEX master_plan_certification_requests_active_level ON public.master_plan_certification_requests(collaborator_id,capability_code,target_level) WHERE status<>'approved'; CREATE UNIQUE INDEX master_plan_certification_requests_approved_level ON public.master_plan_certification_requests(collaborator_id,capability_code,target_level) WHERE status='approved';
CREATE TABLE public.master_plan_journey_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES public.master_plan_certification_requests(id) ON DELETE CASCADE,actor_collaborator_id uuid NOT NULL REFERENCES public.collaborators(id),event_type text NOT NULL CHECK(event_type IN('submitted','approved','changes_requested')),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.master_plan_journey_events TO authenticated; GRANT ALL ON public.master_plan_journey_events TO service_role; ALTER TABLE public.master_plan_journey_events ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_journey_events_read ON public.master_plan_journey_events FOR SELECT TO authenticated USING(public.is_admin() OR EXISTS(SELECT 1 FROM public.master_plan_certification_requests request WHERE request.id=request_id AND request.collaborator_id=public.current_collaborator_id())); CREATE INDEX master_plan_journey_events_request_date ON public.master_plan_journey_events(request_id,created_at DESC);
CREATE FUNCTION public.master_plan_assert_current_collaborator(p_collaborator_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF auth.uid() IS NULL OR public.current_collaborator_id() IS NULL OR public.current_collaborator_id() IS DISTINCT FROM p_collaborator_id THEN RAISE EXCEPTION 'current_collaborator_required'; END IF; END; $$;
CREATE FUNCTION public.master_plan_record_self_assessment(p_collaborator_id uuid,p_capability_code text,p_answers smallint[],p_comment text) RETURNS public.master_plan_self_assessments LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE result public.master_plan_self_assessments; BEGIN PERFORM public.master_plan_assert_current_collaborator(p_collaborator_id); IF NOT EXISTS(SELECT 1 FROM public.collaborators WHERE id=p_collaborator_id AND is_active) THEN RAISE EXCEPTION 'active_collaborator_required'; END IF; INSERT INTO public.master_plan_self_assessments(collaborator_id,capability_code,answers,comment) VALUES(p_collaborator_id,p_capability_code,p_answers,trim(p_comment)) RETURNING * INTO result; RETURN result; END; $$;
CREATE FUNCTION public.master_plan_save_certification_request(p_collaborator_id uuid,p_id uuid,p_capability_code text,p_target_level smallint,p_responses jsonb,p_submit boolean DEFAULT false) RETURNS public.master_plan_certification_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE current_request public.master_plan_certification_requests; result public.master_plan_certification_requests; required_criteria jsonb; previous_level integer; criterion jsonb; response jsonb; BEGIN PERFORM public.master_plan_assert_current_collaborator(p_collaborator_id); IF NOT EXISTS(SELECT 1 FROM public.collaborators WHERE id=p_collaborator_id AND is_active) THEN RAISE EXCEPTION 'active_collaborator_required'; END IF; IF p_target_level NOT BETWEEN 1 AND 3 OR p_responses IS NULL OR jsonb_typeof(p_responses)<>'object' OR octet_length(p_responses::text)>500000 THEN RAISE EXCEPTION 'invalid_certification_request'; END IF; IF EXISTS(SELECT 1 FROM jsonb_each(p_responses) entry WHERE entry.value ? 'files' AND entry.value->'files'<>'[]'::jsonb) THEN RAISE EXCEPTION 'file_evidence_requires_verified_access'; END IF; SELECT criteria INTO required_criteria FROM public.master_plan_capability_library WHERE code=p_capability_code; IF required_criteria IS NULL THEN RAISE EXCEPTION 'unknown_capability'; END IF; SELECT coalesce(max(target_level),0) INTO previous_level FROM public.master_plan_certification_requests WHERE collaborator_id=p_collaborator_id AND capability_code=p_capability_code AND status='approved'; IF p_target_level<=previous_level THEN RAISE EXCEPTION 'level_already_approved'; END IF; IF p_id IS NOT NULL THEN SELECT * INTO current_request FROM public.master_plan_certification_requests WHERE id=p_id FOR UPDATE; IF NOT FOUND OR current_request.collaborator_id<>p_collaborator_id OR current_request.capability_code<>p_capability_code OR current_request.target_level<>p_target_level OR current_request.status NOT IN('draft','changes_requested') THEN RAISE EXCEPTION 'request_not_editable'; END IF; END IF; IF p_submit THEN FOR criterion IN SELECT value FROM jsonb_array_elements(required_criteria) WHERE (value->>'level')::integer<=p_target_level AND (previous_level=0 OR (value->>'level')::integer>previous_level) LOOP response:=p_responses->(criterion->>'id'); IF response IS NULL OR response->>'complete' IS DISTINCT FROM 'true' OR length(trim(coalesce(response->>'explanation','')))=0 OR ((criterion->>'kind')='evidence' AND length(trim(coalesce(response->>'reference','')))=0 AND jsonb_array_length(coalesce(response->'files','[]'::jsonb))=0) THEN RAISE EXCEPTION 'criterion_incomplete: %',criterion->>'id'; END IF; END LOOP; END IF; IF p_id IS NULL THEN INSERT INTO public.master_plan_certification_requests(collaborator_id,capability_code,target_level,status,responses,submitted_at) VALUES(p_collaborator_id,p_capability_code,p_target_level,CASE WHEN p_submit THEN 'submitted' ELSE 'draft' END,p_responses,CASE WHEN p_submit THEN now() ELSE NULL END) RETURNING * INTO result; ELSE UPDATE public.master_plan_certification_requests SET responses=p_responses,reviews=CASE WHEN p_submit THEN '{}'::jsonb ELSE reviews END,status=CASE WHEN p_submit THEN 'submitted' ELSE 'draft' END,submitted_at=CASE WHEN p_submit THEN now() ELSE submitted_at END,updated_at=now() WHERE id=p_id RETURNING * INTO result; END IF; IF p_submit THEN INSERT INTO public.master_plan_journey_events(request_id,actor_collaborator_id,event_type,payload) VALUES(result.id,p_collaborator_id,'submitted',jsonb_build_object('responses',p_responses,'targetLevel',p_target_level)); END IF; RETURN result; END; $$;
CREATE FUNCTION public.master_plan_review_certification_request(p_reviewer_id uuid,p_id uuid,p_reviews jsonb,p_decision text) RETURNS public.master_plan_certification_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE current_request public.master_plan_certification_requests; required_criteria jsonb; previous_level integer; criterion jsonb; result public.master_plan_certification_requests; actor_id uuid:=public.current_collaborator_id(); BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'admin_profile_required'; END IF; PERFORM public.master_plan_assert_current_collaborator(p_reviewer_id); IF p_decision NOT IN('approved','changes_requested') OR p_reviews IS NULL OR jsonb_typeof(p_reviews)<>'object' OR octet_length(p_reviews::text)>200000 THEN RAISE EXCEPTION 'invalid_review'; END IF; SELECT * INTO current_request FROM public.master_plan_certification_requests WHERE id=p_id FOR UPDATE; IF NOT FOUND OR current_request.status<>'submitted' THEN RAISE EXCEPTION 'request_not_reviewable'; END IF; SELECT criteria INTO required_criteria FROM public.master_plan_capability_library WHERE code=current_request.capability_code; SELECT coalesce(max(target_level),0) INTO previous_level FROM public.master_plan_certification_requests WHERE collaborator_id=current_request.collaborator_id AND capability_code=current_request.capability_code AND status='approved' AND id<>p_id; IF current_request.target_level<=previous_level THEN RAISE EXCEPTION 'level_already_approved'; END IF; IF p_decision='approved' THEN FOR criterion IN SELECT value FROM jsonb_array_elements(required_criteria) WHERE (value->>'level')::integer<=current_request.target_level AND (previous_level=0 OR (value->>'level')::integer>previous_level) LOOP IF p_reviews->(criterion->>'id')->>'decision' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'criterion_not_accepted: %',criterion->>'id'; END IF; END LOOP; ELSIF NOT EXISTS(SELECT 1 FROM jsonb_each(p_reviews) WHERE value->>'decision'='changes_requested' AND length(trim(coalesce(value->>'note','')))>0) THEN RAISE EXCEPTION 'review_note_required'; END IF; UPDATE public.master_plan_certification_requests SET reviews=p_reviews,status=p_decision,decided_at=now(),reviewed_by=actor_id,updated_at=now() WHERE id=p_id RETURNING * INTO result; INSERT INTO public.master_plan_journey_events(request_id,actor_collaborator_id,event_type,payload) VALUES(p_id,actor_id,p_decision,jsonb_build_object('reviews',p_reviews)); RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.master_plan_assert_current_collaborator(uuid),public.master_plan_record_self_assessment(uuid,text,smallint[],text),public.master_plan_save_certification_request(uuid,uuid,text,smallint,jsonb,boolean),public.master_plan_review_certification_request(uuid,uuid,jsonb,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.master_plan_record_self_assessment(uuid,text,smallint[],text),public.master_plan_save_certification_request(uuid,uuid,text,smallint,jsonb,boolean),public.master_plan_review_certification_request(uuid,uuid,jsonb,text) TO authenticated;